export interface RateLimiterOptions {
  max: number
  windowMs: number
  mode: 'fixed' | 'sliding'
}

interface FixedBucket {
  windowStart: number
  count: number
}

export class RateLimiter {
  private readonly max: number
  private readonly windowMs: number
  private readonly mode: 'fixed' | 'sliding'
  private readonly fixedBuckets = new Map<string, FixedBucket>()
  private readonly slidingTimestamps = new Map<string, number[]>()

  constructor(options: RateLimiterOptions) {
    this.max = options.max
    this.windowMs = options.windowMs
    this.mode = options.mode
  }

  allow(key: string): boolean {
    const now = Date.now()
    return this.mode === 'fixed'
      ? this.allowFixed(key, now)
      : this.allowSliding(key, now)
  }

  private allowFixed(key: string, now: number): boolean {
    const windowStart = Math.floor(now / this.windowMs) * this.windowMs
    const bucket = this.fixedBuckets.get(key)
    if (!bucket || bucket.windowStart !== windowStart) {
      this.fixedBuckets.set(key, { windowStart, count: 1 })
      return true
    }
    if (bucket.count >= this.max) return false
    bucket.count++
    return true
  }

  private allowSliding(key: string, now: number): boolean {
    const cutoff = now - this.windowMs
    const timestamps = this.slidingTimestamps.get(key) ?? []
    while (timestamps.length > 0 && timestamps[0] <= cutoff) {
      timestamps.shift()
    }
    if (timestamps.length >= this.max) {
      this.slidingTimestamps.set(key, timestamps)
      return false
    }
    timestamps.push(now)
    this.slidingTimestamps.set(key, timestamps)
    return true
  }
}

import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest'
import { RateLimiter } from '../src/rate-limiter'

describe('RateLimiter', () => {
  beforeEach(() => {
    vi.useFakeTimers()
    vi.setSystemTime(new Date('2026-01-01T00:00:00Z'))
  })

  afterEach(() => {
    vi.useRealTimers()
  })

  it('allows the first request', () => {
    const limiter = new RateLimiter({ max: 5, windowMs: 1000, mode: 'fixed' })
    expect(limiter.allow('user-1')).toBe(true)
  })

  it('blocks the request after max in fixed mode', () => {
    const limiter = new RateLimiter({ max: 5, windowMs: 1000, mode: 'fixed' })
    for (let i = 0; i < 5; i++) limiter.allow('user-1')
    expect(limiter.allow('user-1')).toBe(false)
  })

  it('honors a configurable max value', () => {
    const limiter = new RateLimiter({ max: 2, windowMs: 1000, mode: 'fixed' })
    expect(limiter.allow('user-1')).toBe(true)
    expect(limiter.allow('user-1')).toBe(true)
    expect(limiter.allow('user-1')).toBe(false)
  })

  it('tracks each key independently', () => {
    const limiter = new RateLimiter({ max: 2, windowMs: 1000, mode: 'fixed' })
    limiter.allow('user-1')
    limiter.allow('user-1')
    expect(limiter.allow('user-1')).toBe(false)
    expect(limiter.allow('user-2')).toBe(true)
  })

  it('resets the count when the fixed window ends', () => {
    const limiter = new RateLimiter({ max: 2, windowMs: 1000, mode: 'fixed' })
    limiter.allow('user-1')
    limiter.allow('user-1')
    expect(limiter.allow('user-1')).toBe(false)
    vi.advanceTimersByTime(1000)
    expect(limiter.allow('user-1')).toBe(true)
  })

  it('blocks subsequent calls in sliding mode within the trailing window', () => {
    const limiter = new RateLimiter({ max: 5, windowMs: 1000, mode: 'sliding' })
    for (let i = 0; i < 5; i++) limiter.allow('user-1')
    vi.advanceTimersByTime(500)
    expect(limiter.allow('user-1')).toBe(false)
  })

  it('blocks in sliding mode across a fixed-window boundary when calls have not aged out', () => {
    const limiter = new RateLimiter({ max: 5, windowMs: 1000, mode: 'sliding' })
    vi.advanceTimersByTime(500)
    for (let i = 0; i < 5; i++) limiter.allow('user-1')
    vi.advanceTimersByTime(500)
    expect(limiter.allow('user-1')).toBe(false)
  })

  it('allows again in sliding mode once the oldest call ages out', () => {
    const limiter = new RateLimiter({ max: 5, windowMs: 1000, mode: 'sliding' })
    for (let i = 0; i < 5; i++) limiter.allow('user-1')
    vi.advanceTimersByTime(1100)
    expect(limiter.allow('user-1')).toBe(true)
  })
})

